const fs = require('fs');

module.exports = async ({ github, context, core }) => {
  const reportPath =
    process.env.POLICY_REPORT_PATH ||
    'build/reports/cyclonedx/runtime-vulnerability-policy.md';

  const marker = '<!-- runtime-sbom-vulnerability-policy -->';

  if (!fs.existsSync(reportPath)) {
    core.warning(`Runtime SBOM policy report not found: ${reportPath}`);
    return;
  }

  const report = fs.readFileSync(reportPath, 'utf8');
  const body = `${marker}
${report}

---
_Generated by the Runtime SBOM vulnerability policy gate._`;

  const { data: comments } = await github.rest.issues.listComments({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    per_page: 100
  });

  const existing = comments.find(comment =>
    comment.body?.includes(marker)
  );

  if (existing) {
    await github.rest.issues.updateComment({
      owner: context.repo.owner,
      repo: context.repo.repo,
      comment_id: existing.id,
      body
    });

    core.info(`Updated Runtime SBOM PR comment ${existing.id}`);
    return;
  }

  const { data: comment } = await github.rest.issues.createComment({
    owner: context.repo.owner,
    repo: context.repo.repo,
    issue_number: context.issue.number,
    body
  });

  core.info(`Created Runtime SBOM PR comment ${comment.id}`);
};
